# 에필로그 새 문장 번역 7: 첫 해 사건(2차분 앞쪽)
TR = {}
def T(en, en_m, ja1, ja2, ja3): return [(en, ja1), (en, ja2), (en_m, ja3)]
def E_(p, d): TR.update({p + '.' + i: v for i, v in d.items()})
E_('b_bike', {
'b0': ("{N} came home wheeling a secondhand bicycle. They did not know how to ride it, they said. A horse they could ride.", "{N}が中古の自転車を引いて帰ってきた。乗り方は知らないと言った。馬なら乗れると言った。"),
'b1': ("There is a cycle path by the river. {N} watched the people going by for a long while, then said they wanted to learn that.", "川沿いに自転車道がある。{N}は通り過ぎる人たちをしばらく見て、あれを習いたいと言った。"),
'b2': ("There was a bandage on {N}'s knee. They had fallen practicing alone. It seemed they had meant to tell no one.", "{N}の膝に絆創膏が貼られていた。一人で練習して転んだのだ。誰にも言わないつもりだったらしい。"),
'hold.t': ("Hold the back for them", "後ろを支える"),
'hold.r0': ("{N} only realized you had let go a hundred meters on. They looked back and fell, laughing as they fell.", "手を離されたことに{N}が気づいたのは、百メートル先だった。振り返って転び、転びながら笑った。"),
'hold.r1': T("“You let go. Without a word. …Well done.”", "Far off, {N} thrust one hand high. They were riding alone.", "「離したな。何も言わずに。……よくやった」", "「離しましたね。何も言わずに。……お見事です」", "遠くで{N}が片手を高く上げた。一人で走っていた。"),
'hold.r2': ("By sundown {N} had passed you. And it stayed that way ever after.", "日暮れ頃には、{N}があなたを追い越していた。それからはずっとそうだった。"),
'watch.t': ("Cheer from the bench", "ベンチから応援する"),
'watch.r0': ("Twelve falls, and on the thirteenth try they went. Not once did {N} ask for help.", "十二回転んで、十三回目に走った。{N}は一度も助けを求めなかった。"),
'watch.r1': ("{N} came back covered in dirt and took the water bottle. The face of a conqueror.", "{N}が泥だらけで戻ってきて、水筒を受け取った。征服した顔だった。"),
'watch.r2': T("“You were watching? Then that is enough.”", "Catching their breath, {N} gave you a thumbs-up.", "「見ていたか。ならいい」", "「見ていてくださいましたか。なら十分です」", "{N}が息を整えながら、あなたに親指を立ててみせた。"),
})
E_('b_pot', {
'b0': ("{N} came home with a flowerpot. What would grow in it, they did not know. The florist had simply given it to them.", "{N}が鉢をひとつ持って帰ってきた。何が育つのかは分からないと言った。花屋の主人がただでくれたのだと。"),
'b1': ("A handful of soil appeared on the balcony. {N} said they wanted to try growing something. They had cut down much, and never grown anything.", "ベランダに一握りの土ができた。{N}が何かを育ててみたいと言った。斬ったことは多くても、育てたことはないのだと。"),
'b1@civil': ("A handful of soil appeared on the balcony. {N} said they wanted to try growing something. Not something in the head, but something that lives and grows.", "ベランダに一握りの土ができた。{N}が何かを育ててみたいと言った。頭の中のものではなく、生きて育つものを。"),
'b2': ("Every morning {N} crouches before the pot to see whether it has sprouted. Not yet.", "{N}は毎朝、鉢の前にしゃがむ。芽が出たか見ているのだ。まだ出ていない。"),
'water.t': ("Show them how to water it", "水のやり方を教える"),
'water.r0': ("The day it sprouted, {N} came to wake you. It was five in the morning.", "芽が出た日、{N}はあなたを起こしに来た。朝の五時だった。"),
'water.r1': T("“There is nothing to do but wait. An unfamiliar battle.”", "{N} pressed the soil with a finger and set down the watering can. That was all for today.", "「待つことしかできないのか。慣れない戦いだ」", "「待つことしかできないのですね。慣れない戦いです」", "{N}が土を指で押してみて、如雨露を置いた。今日はここまでだった。"),
'water.r2': ("Too much water nearly killed it once. After that {N} wrote the watering days on the calendar.", "水をやりすぎて一度枯れかけた。それから{N}は暦に水やりの日を書いた。"),
'name.t': ("Suggest giving it a name", "名前をつけようと言う"),
'name.r0': ("The name {N} gave was grand. Too much name for a sprout the size of a finger. You decided to use it as it was.", "{N}のつけた名前は大仰だった。指ほどの芽には過ぎた名前だった。そのまま呼ぶことにした。"),
'name.r1': ("Once it had a name, {N} began to speak to the pot. Like a report, once a day.", "名前がつくと、{N}は鉢に話しかけるようになった。報告のように、一日一度。"),
'name.r2': T("“Having given it a name, I bear the responsibility. That is the rule.”", "{N} stuck a name tag in the pot. The lettering was neat.", "「名を与えたからには責任も負う。そういうものだ」", "「名を与えたからには責任も負います。そういうものです」", "{N}が鉢に名札を挿した。字が整っていた。"),
})
E_('b_friend', {
'b0': ("{N} has made a friend. Someone you do not know. They met playing chess in the neighborhood park, they said.", "{N}に友人ができた。あなたの知らない人だ。近所の公園で将棋を指していて知り合ったと言った。"),
'b1': ("Someone came looking for {N}. Someone from work, they said. It was the first time you saw {N} laugh with anyone but you.", "誰かが{N}を訪ねてきた。職場で知り合った人だと言った。{N}があなた以外の人と笑うのを初めて見た。"),
'b2': ("One more name appeared in {N}'s phone. The second name, after yours.", "{N}の電話に名前がひとつ増えた。あなたの次の、二つ目の名前だった。"),
'glad.t': ("Say you're glad", "良かったと言う"),
'glad.r0': ("{N} looked a little surprised. It seems they had meant to ask permission. That day they learned there was no need.", "{N}は少し驚いた顔だった。許しを求めるつもりだったらしい。その必要がないことを、その日知った。"),
'glad.r1': T("“Someone besides my Master now calls me by name. A strange feeling.”", "{N} pointed at the two names in the phone by turns and smiled sheepishly.", "「マスター以外にも私の名を呼ぶ者ができた。妙な気分だ」", "「マスター以外にも私の名前を呼ぶ人ができました。不思議な気分です」", "{N}が電話の二つの名前を交互に指して、照れくさそうに笑った。"),
'glad.r2': ("That evening {N} talked about the friend for a long time. You enjoyed listening.", "その夕方、{N}は友人の話を長くした。あなたは聞くのが楽しかった。"),
'meet.t': ("Ask to be introduced", "一度紹介してほしいと言う"),
'meet.r0': ("The three of you ate together. {N}'s friend was a good person, and knew {N} only as someone a bit eccentric.", "三人で食事をした。{N}の友人は良い人で、{N}のことを少し変わった人だとしか知らなかった。"),
'meet.r1': ("The friend asked how you two had met. Your eyes met {N}'s. In winter, was all you said.", "友人が尋ねた。二人はどうやって出会ったのかと。{N}と目が合った。冬に出会ったとだけ言った。"),
'meet.r2': T("“Showing one of my people to another. A good day.”", "{N} sat between you and the friend, looking from one to the other and smiling the whole time.", "「私の大切な者を、私の大切な者に見せているのか。良い日だ」", "「私の大切な人を、私の大切な人にお見せしているのですね。良い日です」", "{N}があなたと友人の間に座って、両方を交互に見ながらずっと笑っていた。"),
})
E_('b_gift', {
'b0': ("{N} stood hiding something behind their back. The first thing they had bought with money they earned, they said.", "{N}が背中に何かを隠して立っていた。自分で稼いだ金で初めて買った物だと言った。"),
'b1': ("On the table was a clumsily wrapped box. The ribbon had been tied three times.", "食卓の上に、不器用に包まれた箱があった。リボンが三度結ばれていた。"),
'b2': ("For days {N} had been going to look in one shop window. Today you learned why.", "何日も、{N}はある店の陳列窓を覗きに通っていた。今日、その理由が分かった。"),
'open.t': ("Open it on the spot", "その場で開けてみる"),
'open.r0': ("What was inside was not expensive. It was something you had mentioned once in passing. {N} had remembered.", "中に入っていたのは高価な物ではなかった。あなたが通りすがりに一度口にした物だった。{N}はそれを覚えていた。"),
'open.r1': T("“It is not tribute. I give it simply because I want to. I have never done this before.”", "{N} held their breath the whole time you were unwrapping it.", "「貢ぎ物ではない。ただ贈りたくて贈るのだ。初めてやる」", "「捧げ物ではありません。ただ差し上げたくて差し上げるのです。初めてです」", "{N}はあなたが包みを解く間、ずっと息を止めていた。"),
'open.r2': ("It was not a very useful thing. You put it where it could best be seen.", "あまり役に立たない物だった。あなたはそれを、いちばんよく見える場所に置いた。"),
'back.t': ("Prepare a gift in return", "お返しを用意する"),
'back.r0': ("A few days later you held something out too. {N} was the clumsier one at receiving.", "数日後、あなたも何かを差し出した。{N}は受け取る方が不器用だった。"),
'back.r1': ("Giving and receiving. {N} learned it for the first time in this world. In life, they said, it was either taking or bestowing.", "贈り、贈られること。{N}はそれをこの世界で初めて覚えた。生前は奪うか下賜するかのどちらかだったと言った。"),
'back.r1@now': ("Giving and receiving. {N} said it had been a long time. There was a long stretch of only giving.", "贈り、贈られること。{N}はそれが久しぶりだと言った。与えるばかりの頃が長かったと。"),
'back.r1@civil': ("Giving and receiving. {N} was clumsy at it. In life, they said, they knew only handing over a work and taking its price.", "贈り、贈られること。{N}はそれが不器用だった。生前は作品を出して代価を受け取ることしか知らなかったと言った。"),
'back.r2': T("“You mean to repay me? Then I must repay you again.”", "{N} held what they had received in both hands and smiled, at a loss.", "「返すつもりか。それでは私がまた返さねばならなくなる」", "「お返しのつもりですか？それでは私がまたお返ししないといけなくなります」", "{N}がもらった物を両手に持って、どうしていいか分からない顔で笑った。"),
})
E_('b_side', {
'b0': ("{N} stole a glance at a message that came for you. An unfamiliar name. They did not ask. Their face wanted to.", "あなたに届いた連絡を、{N}が横目で見た。知らない名前だった。訊きはしなかった。訊きたい顔だった。"),
'b1': ("The work dinner ran late. When you got home, {N} was sitting without even a light on.", "職場の宴会が長引いた。帰ると、{N}が灯りもつけずに座っていた。"),
'b2': ("An old friend of yours came to visit. {N} said it was the first time they had seen you laugh like that.", "あなたの古い友人が遊びに来た。あなたがあんなふうに笑うのを、{N}は初めて見ると言った。"),
'tell.t': ("Tell them about each one", "ひとりひとり話して聞かせる"),
'tell.r0': ("You told them the names, the faces, the stories. {N} listened to the end and said they were glad your world was wide. A little vexed, too.", "名前と顔と事情をすべて聞かせた。{N}は最後まで聞いて言った。あなたの世界が広くて良かったと。少し悔しいとも。"),
'tell.r1': T("“I do not know your past. That was all that weighed on me.”", "{N} fetched your album and opened it on their knees. It meant: show me from the beginning.", "「お前の昔を私は知らない。それが少し引っかかっただけだ」", "「あなたの昔を私は知りません。それが少し引っかかっただけです」", "{N}があなたのアルバムを持ってきて膝の上に開いた。最初から見せてくれという意味だった。"),
'tell.r2': ("That night passed in stories of your past. {N} asked and you answered. The reverse of that winter.", "その夜は、あなたの昔話で過ぎていった。{N}が尋ね、あなたが答えた。あの冬とは逆だった。"),
'tease.t': ("Tease them about being jealous", "やきもちかとからかう"),
'tease.r0': T("“…And if I said yes, what would you do?” {N} did not look away.", "Instead of answering, {N} sat down right up against your side.", "「……そうだと言ったら、どうする」{N}は目を逸らさなかった。", "「……そうだと言ったら、どうなさいますか」{N}は目を逸らさなかった。", "{N}は答える代わりに、あなたの隣にぴったりくっついて座った。"),
'tease.r1': ("{N} said no. Their ears did not say no.", "{N}は違うと言った。耳は違うと言っていなかった。"),
'tease.r2': ("You were the one who teased, and yours was the face that went hot.", "からかったのはあなたなのに、顔が熱くなったのもあなただった。"),
})
E_('b_home', {
'b0': ("The holidays were coming. You had to go to your family home. Take {N}, or leave them — you had to decide.", "連休が近づいた。実家に帰らなければならない。{N}を連れて行くか、置いて行くか決めなければならなかった。"),
'b1': ("Your family said: you live with someone now, so bring them once.", "家族が言った。一緒に暮らしている人がいるそうだが、一度連れてきなさいと。"),
'b2': ("Looking at the red-letter days on the calendar, {N} asked where you would be that day.", "{N}が暦の赤い日を見て尋ねた。その日、あなたはどこにいるのかと。"),
'take.t': ("Go together", "一緒に行く"),
'take.r0': ("At the door {N} straightened their clothes three times. The elders were charmed by {N}'s manners and astonished by their appetite.", "{N}は扉の前で三度身なりを整えた。年長者たちは{N}の礼儀に感心し、食べる量に驚いた。"),
'take.r1': T("“So this is the house you grew up in. There are marks on the post where your height was measured.”", "{N} ran a finger up the old marks on the doorpost. At the topmost one they looked back at you.", "「お前の育った家か。柱に背丈を測った跡があるな」", "「あなたの育った家ですね。柱に背丈を測った跡があります」", "{N}が柱の古い刻みを指で辿って上っていった。いちばん上で、あなたを振り返った。"),
'take.r2': ("On the way back {N} carried everything your family had packed. They had been told to come again, {N} said — twice.", "帰り道、家族が持たせてくれた物を{N}がすべて持った。また来なさいと言われたと、二度言った。"),
'alone.t': ("Go alone", "一人で行ってくる"),
'alone.r0': ("Three days. When you returned, the house was excessively clean. {N} had gone looking for things to do.", "三日だった。戻ると、家がやけにきれいだった。{N}がすることを探してやったのだ。"),
'alone.r1': ("From your family home you called {N}. There was no reason. Your family asked who it was.", "実家から{N}に電話をかけた。用はなかった。家族が誰なのかと訊いた。"),
'alone.r2': T("“You are back. …They were long, those three days.”", "You opened the door to find {N} standing in the entryway. They had heard your footsteps and come out.", "「戻ったか。……長かったな、三日は」", "「お帰りなさい。……長かったです、三日は」", "扉を開けると、{N}が玄関に立っていた。足音を聞いて出てきていたのだ。"),
})
E_('b_storm', {
'b0': ("A typhoon came. In the evening the power went out. The whole neighborhood went dark.", "台風が来た。夕方、電気が止まった。町じゅうが真っ暗になった。"),
'b1': ("Wind shook the windows. A blackout. In the dark, {N} found the candles before you did.", "風が窓を揺らした。停電だった。{N}が暗闇の中で、あなたより先に蝋燭を見つけた。"),
'b2': ("The sound of wind and rain was like the nights of that winter. When the lights went out, {N}'s body tensed first.", "風雨の音があの冬の夜のようだった。灯りが消えると、{N}の体が先に強張った。"),
'candle.t': ("Light a candle and sit", "蝋燭を灯して座る"),
'candle.r0': ("Two faces in the light of one candle. {N} said the nights they had lived were always like this. This was the familiar way.", "一本の蝋燭に二つの顔が映った。{N}が言った。自分の生きた夜はいつもこうだったと。こちらの方が慣れていると。"),
'candle.r0@now': ("Two faces in the light of one candle. {N} said they had passed many nights without electricity. Back then, alone.", "一本の蝋燭に二つの顔が映った。{N}が言った。電気のない夜を何度も過ごしたことがあると。あの頃は一人だったと。"),
'candle.r0@modern': ("Two faces in the light of one candle. {N} said half the nights of their day were like this. They did not miss it.", "一本の蝋燭に二つの顔が映った。{N}が言った。自分の時代の夜も半分はこうだったと。懐かしくはないと。"),
'candle.r1': T("“One flame is enough. Everything worth seeing can be seen.”", "{N} moved the candle to the exact middle between you.", "「灯りはひとつで足りるな。見るべきものはすべて見える」", "「灯りはひとつで足りますね。見るべきものはすべて見えます」", "{N}が蝋燭を二人のちょうど真ん中へ移した。"),
'candle.r2': ("The talk ran long. The power came back before dawn, and neither of you turned on a light.", "話が長くなった。電気は明け方に戻ったが、二人とも灯りをつけなかった。"),
'check.t': ("Go over the house together", "家を一緒に見回る"),
'check.r0': ("{N} taped every window. The hands of someone repairing a rampart.", "{N}が窓ごとにテープを貼った。城壁を修繕する手つきだった。"),
'check.r1': ("Bring in the balcony pots, store water, find the flashlight. {N} was used to sieges.", "ベランダの鉢を入れ、水を溜め、懐中電灯を用意した。{N}は籠城に慣れていた。"),
'check.r2': T("“The enemy is wind. Hold out and we win. An easy battle.”", "{N} latched the last window and dusted off their hands. Preparations were complete.", "「敵は風だ。耐えれば勝つ。易しい戦いだな」", "「相手は風です。耐えれば勝ちます。易しい戦いですね」", "{N}が最後の窓に鍵をかけ、手を払った。支度が済んだという意味だった。"),
})
E_('b_bday', {
'b0': ("{N} had found out your birthday from somewhere. They were suspicious from the morning on.", "{N}がどこかであなたの誕生日を突き止めていた。朝から様子が怪しかった。"),
'b1': ("There was a cake with candles on the table. The number of candles was wrong. It seemed {N} had given up counting.", "食卓に蝋燭の立ったケーキがあった。蝋燭の数が合っていなかった。{N}が数えるのを諦めたらしい。"),
'b2': ("{N} asked what people of this age do on the day they were born. They asked already knowing that tomorrow was that day.", "{N}が尋ねた。この時代では生まれた日に何をするのかと。明日がその日だと、とうに知っていて訊いたのだった。"),
'b2@now': ("{N} asked what kind of cake you like. They asked already knowing that tomorrow was that day.", "{N}が尋ねた。ケーキはどんなものが好きかと。明日がその日だと、とうに知っていて訊いたのだった。"),
'b2@modern': ("{N} asked what kind of cake you like. They asked already knowing that tomorrow was that day.", "{N}が尋ねた。ケーキはどんなものが好きかと。明日がその日だと、とうに知っていて訊いたのだった。"),
'wish.t': ("Make a wish", "願い事をする"),
'wish.r0': ("You blew out the candles. {N} asked what you had wished for. Told that saying it would undo it, they nodded gravely.", "蝋燭を吹き消した。{N}が何を願ったのかと尋ねた。言うと叶わないのだと答えると、真面目な顔で頷いた。"),
'wish.r1': T("“A wish made without the Grail. I think that kind comes true more readily.”", "While your eyes were closed, {N} had theirs closed too.", "「聖杯なしで願う願いか。その方がよく叶いそうだな」", "「聖杯なしで願う願いですね。その方がよく叶いそうです」", "{N}は、あなたが目を閉じている間、一緒に目を閉じていた。"),
'wish.r2': ("You could think of nothing to wish for. It was already sitting across the table.", "願うことが思い浮かばなかった。もう食卓の向かいに座っていたからだ。"),
'eat.t': ("Start on the cake", "まずケーキを食べる"),
'eat.r0': ("{N} ate three slices of cake. On your birthday.", "{N}はケーキを三切れ食べた。あなたの誕生日なのに。"),
'eat.r1': ("There was cream on {N}'s nose. You did not tell them.", "{N}の鼻にクリームがついた。教えなかった。"),
'eat.r2': T("“I celebrate that you were born. Thanks to it, I am here.”", "{N} put down the fork and bowed deeply to you.", "「生まれたことを祝う。おかげで私がここにいる」", "「お生まれになったことをお祝いします。おかげで私がここにいます」", "{N}がフォークを置いて、あなたに深く頭を下げた。"),
})
E_('b_hday', {
'b0': ("{N}'s birthday was in no book. They did not know it themselves, they said. You decided to settle on a day to use in this world.", "{N}の誕生日はどの本にもなかった。本人も知らないと言った。この世界で使う日をひとつ決めることにした。"),
'b0@now': ("{N} could not remember their birthday. It certainly existed, they said, but the date had worn away. You decided to settle on a day to use in this world.", "{N}は自分の誕生日を覚えていなかった。確かにあったのだが、日付が擦り切れたのだと言った。この世界で使う日をひとつ決めることにした。"),
'b1': ("The form had a box for date of birth. {N} held the pen above it for a long time.", "書類に生年月日の欄があった。{N}はしばらくペンを持ったままでいた。"),
'b2': ("Turning the calendar, {N} asked whether they too might have one day to be celebrated.", "{N}が暦をめくりながら言った。自分にも祝われる日が一日あってもいいだろうかと。"),
'summon.t': ("Make it the day they were summoned", "召喚された日にする"),
'summon.r0': ("That night of that winter became {N}'s birthday. Not the day the fighting began, but the day you met.", "あの冬のあの夜が、{N}の誕生日になった。戦いの始まった日ではなく、出会った日だった。"),
'summon.r1': T("“I was born again that day, in a sense. Not a wrong date.”", "{N} circled that date on the calendar twice.", "「あの日に生まれ直したようなものだ。間違った日付ではないな」", "「あの日に生まれ直したようなものです。間違った日付ではありませんね」", "{N}が暦のその日に、丸を二重につけた。"),
'summon.r2': ("One more mark on the calendar. Next year on that day, you agreed, there would be one candle.", "暦に印がひとつ増えた。来年のその日には、蝋燭を一本立てることにした。"),
'pick.t': ("Let them choose a day they like", "気に入った日を選ばせる"),
'pick.r0': ("The day {N} chose was no special day. Just a day when the weather had been fine. The first day they fell asleep without a single worry, they said.", "{N}が選んだのは何の日でもなかった。ただ天気の良かったある一日だった。初めて何の心配もなく眠った日だと言った。"),
'pick.r1': ("It took three days of thought to choose. They would not say why. They would tell you next year.", "三日悩んで選んだ日だった。理由は教えてくれなかった。来年教えると言った。"),
'pick.r2': T("“A birthday of my own choosing. A luxury. I like it.”", "{N} put a finger on one square of the calendar and looked at you. It meant: here.", "「自分で決める誕生日か。贅沢なものだ。気に入った」", "「自分で決める誕生日だなんて。贅沢ですね。気に入りました」", "{N}が暦のひとつの枡に指を置いて、あなたを見た。ここだという意味だった。"),
})
